import{_ as r,c as t,o,ag as i}from"./chunks/framework.CQuhCYrb.js";const d=JSON.parse('{"title":"Router Hardening","description":"","frontmatter":{"title":"Router Hardening"},"headers":[],"relativePath":"general/router-hardening.md","filePath":"general/router-hardening.md","lastUpdated":null}'),a={name:"general/router-hardening.md"};function n(s,e,l,u,c,p){return o(),t("div",null,[...e[0]||(e[0]=[i('<h1 id="router-hardening" tabindex="-1">Router Hardening <a class="header-anchor" href="#router-hardening" aria-label="Permalink to &quot;Router Hardening&quot;">​</a></h1><h2 id="wireless-access-point-security-and-privacy" tabindex="-1">Wireless Access Point Security and Privacy <a class="header-anchor" href="#wireless-access-point-security-and-privacy" aria-label="Permalink to &quot;Wireless Access Point Security and Privacy&quot;">​</a></h2><p>For the full DFP Guides, see <a href="/general/dfp-guide.html">Guide</a></p><p>This page provides guidelines and recommendations for configuring wireless access points (WAP), commonly referred to as routers, to enhance users’ security and privacy.</p><h3 id="resources-for-home-network-security" tabindex="-1">Resources for Home Network Security <a class="header-anchor" href="#resources-for-home-network-security" aria-label="Permalink to &quot;Resources for Home Network Security&quot;">​</a></h3><p>Here are some excellent guides and resources on the web for home network security:</p><h3 id="nsa-best-practices-for-securing-your-home-network" tabindex="-1">NSA Best Practices for Securing Your Home Network <a class="header-anchor" href="#nsa-best-practices-for-securing-your-home-network" aria-label="Permalink to &quot;NSA Best Practices for Securing Your Home Network&quot;">​</a></h3><ul><li><p>The National Security Agency (NSA) offers a comprehensive guide to help teleworkers protect their home networks from cyber threats. It covers securing various devices, from computers and mobile phones to IoT devices.</p></li><li><p><a href="http://www.nsa.gov/Press-Room/News-Highlights/Article/Article/3304674/nsa-releases-best-practices-for-securing-your-home-network/" target="_blank" rel="noreferrer">NSA Guide</a></p></li></ul><h3 id="a-guide-to-wifi-security-on-home-public-networks-in-2024-proprivacy" tabindex="-1">A Guide to WiFi Security on Home &amp; Public Networks in 2024 - ProPrivacy <a class="header-anchor" href="#a-guide-to-wifi-security-on-home-public-networks-in-2024-proprivacy" aria-label="Permalink to &quot;A Guide to WiFi Security on Home &amp; Public Networks in 2024 - ProPrivacy&quot;">​</a></h3><ul><li><p>This guide by ProPrivacy covers crucial aspects of WiFi security for both home and public networks, including how to access your router’s admin panel and change encryption settings.</p></li><li><p><a href="https://proprivacy.com/guides/wifi-security" target="_blank" rel="noreferrer">ProPrivacy Guide</a></p></li></ul><h3 id="how-to-check-if-your-home-network-is-secure-actionable-tips-proprivacy" tabindex="-1">How to Check if Your Home Network is Secure? | Actionable Tips - ProPrivacy <a class="header-anchor" href="#how-to-check-if-your-home-network-is-secure-actionable-tips-proprivacy" aria-label="Permalink to &quot;How to Check if Your Home Network is Secure? | Actionable Tips - ProPrivacy&quot;">​</a></h3><ul><li><p>ProPrivacy also offers actionable tips to check the security of your home network and ensure it’s secure against potential intrusions.</p></li><li><p><a href="https://proprivacy.com/guides/how-to-check-if-your-home-network-is-secure" target="_blank" rel="noreferrer">ProPrivacy Tips</a></p></li></ul><h3 id="how-to-secure-your-home-network-kaspersky" tabindex="-1">How to Secure Your Home Network - Kaspersky <a class="header-anchor" href="#how-to-secure-your-home-network-kaspersky" aria-label="Permalink to &quot;How to Secure Your Home Network - Kaspersky&quot;">​</a></h3><ul><li><p>Kaspersky’s guide starts with changing your network’s name (SSID) and covers more steps to secure your home network effectively.</p></li><li><p><a href="https://web.archive.org/web/20240715205604/https://www.kaspersky.com/resource-center/preemptive-safety/how-to-set-up-a-secure-home-network" target="_blank" rel="noreferrer">Kaspersky Guide (Archive Link for Obvious Reasons)</a></p></li></ul><h3 id="home-network-security-cisa" tabindex="-1">Home Network Security - CISA <a class="header-anchor" href="#home-network-security-cisa" aria-label="Permalink to &quot;Home Network Security - CISA&quot;">​</a></h3><ul><li><p>The Cybersecurity &amp; Infrastructure Security Agency (CISA) provides insights into home network security, emphasizing the protection of devices connected to and the internet within a home.</p></li><li><p><a href="https://www.cisa.gov/news-events/news/home-network-security" target="_blank" rel="noreferrer">CISA Home Network Security</a></p></li></ul><h3 id="configuration-recommendations" tabindex="-1">Configuration Recommendations <a class="header-anchor" href="#configuration-recommendations" aria-label="Permalink to &quot;Configuration Recommendations&quot;">​</a></h3><h3 id="wireless-router-configuration" tabindex="-1">Wireless Router Configuration <a class="header-anchor" href="#wireless-router-configuration" aria-label="Permalink to &quot;Wireless Router Configuration&quot;">​</a></h3><h4 id="factory-reset-router" tabindex="-1">Factory Reset Router <a class="header-anchor" href="#factory-reset-router" aria-label="Permalink to &quot;Factory Reset Router&quot;">​</a></h4><p>If you have not had total control of the router since it was activated, you should factory reset it using the physical reset button (long press the small button) or through the admin portal. This is important as the router could already be exploited by backdoors, services, or users.</p><p><strong>Logging In Access Admin Portal</strong>: You must access the admin page, typically by going to <code>192.168.1.1</code> in a browser. However, your router’s IP can differ, so check your network settings. <strong>Logging In to the Admin Portal</strong>: The admin password is typically found on the router physically or may be something that you can search online for, such as:</p><ul><li><code>Router_Brand &quot;default admin&quot; (&quot;password&quot; OR &quot;credentials&quot;)</code></li></ul><h4 id="common-router-configuration" tabindex="-1">Common Router Configuration <a class="header-anchor" href="#common-router-configuration" aria-label="Permalink to &quot;Common Router Configuration&quot;">​</a></h4><p>Secure your router effectively by following these key steps, each designed to enhance the security and performance of your network:</p><p><strong>Change the Default Admin Password</strong>: The default password is often simple and known to attackers, making it imperative to change it to prevent unauthorized access. Use a <a href="/general/guide-to-password-managers.html">manager</a>.</p><ul><li><p>Access your router’s admin panel through a web browser.</p></li><li><p>Locate the settings for the <strong>administrative password</strong> or <strong>router password</strong>.</p></li><li><p>Change the default password to a strong, unique passphrase.</p></li><li><p>Save the changes.</p></li></ul><p><strong>Enable WPA3 Encryption</strong>: The latest encryption standard, WPA3, significantly improves network security by making it harder for attackers to crack passwords.</p><ul><li><p>In the router’s admin interface, find the wireless or security settings.</p></li><li><p>Look for the Wi-Fi encryption options and select WPA3. If WPA3 is not available, select WPA2-PSK as an alternative.</p></li><li><p>Generate and save a password with a <a href="/general/guide-to-password-managers.html">manager</a>.</p></li><li><p>Apply and save the settings.</p></li></ul><p><strong>Disable WPS (Wi-Fi Protected Setup)</strong>: While WPS offers convenience by allowing users to connect to the network easily, it also poses a security risk and should be disabled.</p><ul><li><p>Navigate to the wireless or WPS settings within the router’s admin interface.</p></li><li><p>Find the option to disable WPS and select it.</p></li><li><p>Save your changes.</p></li></ul><p><strong>Update Firmware Regularly</strong>: Firmware updates often contain security enhancements and bug fixes, making it crucial to keep your router’s firmware up to date.</p><ul><li><p>Go to the system or firmware update section of your router’s settings.</p></li><li><p>Check for any available firmware updates.</p></li><li><p>Download and install the update following the on-screen instructions. Restart the router if required.</p></li></ul><p><strong>Separate your IoT devices from your main devices</strong>: Internet of Things (IoT) devices (i.e., TV streaming sticks, smart lights, smart speakers, etc.) increase the attack surface and, if compromised, can be used to access other devices on your network. IoT devices often won’t have as robust security architecture/programs as your main devices.</p><ul><li><p>Authenticate IoT devices to only a single network.</p></li><li><p>Recommend 2.4 GHz Guest network (many IoT devices won’t be 5 GHz compatible).</p></li><li><p>Authenticate main devices (i.e., computers, cellphones) to a different network on your router.</p></li></ul><p><strong>Disable Remote Management</strong>: Remote management can be a vulnerability if not used securely, allowing potential external access to your router’s settings.</p><ul><li><p>Locate the remote management or WAN management settings in the router’s admin interface.</p></li><li><p>Ensure remote management is turned off or set to the most restrictive setting possible.</p></li><li><p>Save the changes.</p></li></ul><p><strong>Use a Guest Network</strong>: A guest network isolates visitors’ internet use from your main network, safeguarding your personal data. The guest network isolates your devices and the admin portal from devices on that guest network. DO NOT let guests onto your main (non-guest WIFI).</p><ul><li><p>Find the guest network settings in your router’s configuration.</p></li><li><p>Enable the guest network feature and set a unique SSID (totally unassociated from your main WIFI) and password.</p></li><li><p>Generate and save a password with a <a href="/general/guide-to-password-managers.html">manager</a>.</p></li><li><p>Configure the network to isolate guest users from your main network.</p></li><li><p>Save and apply the settings.</p></li></ul><p><strong>Create a Backup</strong>: Saving a backup of your router’s settings ensures you can quickly restore your network’s configuration in case of a reset or error. Save backup to <a href="/general/guide-to-password-managers.html">manager</a>.</p><ul><li><p>Look for the backup or save settings option in the router’s admin panel.</p></li><li><p>Follow the prompts to create a backup of your current settings.</p></li><li><p>Store the backup file in a secure, encrypted drive.</p></li></ul><p><strong>DNS Configuration</strong>: Changing your DNS settings can not only speed up your internet connection but also add an additional layer of security by blocking malicious sites.</p><ul><li><p>Log into your router’s admin interface.</p></li><li><p>Navigate to the DNS settings section.</p></li><li><p>Replace the default DNS server addresses with a more secure and faster DNS service. Recommended options include:</p><ul><li>Cloudflare: <code>1.1.1.1</code> and <code>1.0.0.1</code></li><li>Quad9: <code>9.9.9.9</code></li></ul></li><li><p>Save your changes and reboot the router if necessary.</p></li></ul><h4 id="travel-router-configuration" tabindex="-1">Travel Router Configuration <a class="header-anchor" href="#travel-router-configuration" aria-label="Permalink to &quot;Travel Router Configuration&quot;">​</a></h4><p>To ensure security and efficiency while using a travel router, follow these configuration steps:</p><p><strong>Connection Methods</strong>: Choose how to connect based on your needs.</p><ul><li><p>For Ethernet: Plug the Ethernet cable from the modem or another network connection into the travel router.</p></li><li><p>For Wireless: Access the travel router’s network settings and configure it to connect to an available Wi-Fi network as a client.</p></li></ul><p><strong>WIFI Name (SSID)</strong>: Customize your network name to avoid identification.</p><ul><li><p>In the router’s settings, find the Wi-Fi or Wireless section.</p></li><li><p>Change the SSID from the default to something unique that doesn’t disclose personal information.</p></li><li><p>Save the changes.</p></li></ul><p><strong>Wireless Power (Range)</strong>: Adjust to manage the coverage area.</p><ul><li><p>Locate the wireless settings in your router’s admin interface.</p></li><li><p>Look for a transmission power setting and adjust it accordingly. Lower it to reduce the range if needed.</p></li><li><p>Apply the changes.</p></li></ul><p><strong>Whitelisting</strong>: Allow only known devices to connect.</p><ul><li><p>Find the MAC Address Filtering or Access Control section in the router settings.</p></li><li><p>Enter the MAC addresses of the devices you wish to allow.</p></li><li><p>Enable the filtering and save your settings.</p></li></ul><p><strong>Regular Factory Reset (Restore from Backup)</strong>: Maintain a clean state.</p><ul><li><p>Perform a factory reset via the router’s admin interface or a physical button, typically held for a few seconds.</p></li><li><p>After resetting, access the router and restore settings from a previously saved encrypted backup file to quickly return to your preferred configuration.</p></li></ul><p><strong>Security Audits</strong>: Ensure your travel router remains secure.</p><ul><li>Regularly log into the router&#39;s admin interface to check for firmware updates.</li></ul>',56)])])}const g=r(a,[["render",n]]);export{d as __pageData,g as default};
